import sys, json
sys.path.insert(0, '/root/autodl-tmp')

# Inline the patched function for testing (avoid importing full grpo_trainer which needs trl)
def _parse_json_output(text):
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        start = text.find("[")
        end = text.rfind("]") + 1
        if start >= 0 and end > start:
            try:
                return json.loads(text[start:end])
            except json.JSONDecodeError:
                return []
    return []

# Read the patched format_reward_fn from grpo_trainer.py
exec(open('/root/autodl-tmp/freige/training/grpo_trainer.py').read().split('def format_reward_fn')[1].split('\ndef ')[0].replace('def format_reward_fn', 'xxx = 1  # skip'), {})

# Manually test the logic
completions = [
    '[{"head": "X", "tail": "Y", "relation": "r", "evidence": [0]}]',
    '[{"head_entity": "X", "tail_entity": "Y", "type": "r", "sentence_ids": [0]}]',
    '[{"head": "X", "tail": "Y", "relation": "r"}]',  # missing evidence
    'not json',
]

for i, text in enumerate(completions):
    parsed = _parse_json_output(text)
    if not isinstance(parsed, list):
        print(f"Completion {i}: reward=0.0 (not a list)")
        continue
    if not parsed:
        print(f"Completion {i}: reward=0.1 (empty)")
        continue
    valid = 0
    for item in parsed:
        if not isinstance(item, dict):
            continue
        has_head = "head" in item or "head_entity" in item
        has_tail = "tail" in item or "tail_entity" in item
        has_rel = "relation" in item or "type" in item or "label" in item
        evi_key = next((k for k in ("evidence", "sentence_ids") if k in item), None)
        has_evi = evi_key is not None and isinstance(item[evi_key], list)
        if has_head and has_tail and has_rel and has_evi:
            valid += 1
    reward = valid / len(parsed)
    print(f"Completion {i}: reward={reward} ({'OK' if reward > 0.5 else 'LOW'})")
PYEOF
